        {wardsOpen && <div className="sidebar-subnav">{item("wards", "Ward Overview", "ward-overview")}{item("chart", "Ward Risk", "ward-risk")}{item("grid", "Population Exposure", "population-exposure")}{item("bell", "Health Impact", "health-impact")}{item("trend", "Ward Trends", "ward-trends")}</div>}
